const d = $input.first().json;
// สร้างข้อความแจ้งเตือนตาม event
const msgMap = {
  TICKET_CREATED: '📋 มี Ticket ใหม่ ' + (d.ticket_id||''),
  STATUS_CHANGED: '🔄 Ticket ' + (d.ticket_id||'') + ' เปลี่ยนสถานะเป็น ' + (d.status||''),
  COMPLETED: '✅ Ticket ' + (d.ticket_id||'') + ' เสร็จแล้ว'
};
return [{ json: { ...d, notif_message: msgMap[d.event] || ('แจ้งเตือน Ticket '+(d.ticket_id||'')) } }];

